 const pinnedMoves=settings.movePriority||[],pinnedFusions=settings.fusionPriority||[];
 const wantedMoves=[...new Set([...p.moves,...moveList.filter(m=>named(pinnedMoves,m.name,m.id)||pinnedMoves.includes(m.key)).map(m=>m.id)])];
 const wantedFusions=[...new Set([...p.fus,...fusionList.filter(f=>named(pinnedFusions,f.name,f.key)).map(f=>f.key)])].filter(k=>!named(settings.fusionNever||[],fusionList.find(f=>f.key===k)?.name,k));
